ALTER TABLE question DROP CONSTRAINT IF EXISTS question_status_check;
ALTER TABLE question ADD CONSTRAINT question_status_check CHECK(status IN ('DRAFT','SUBMITTED','CHANGES_REQUESTED','APPROVED','PUBLISHED','ARCHIVED'));
ALTER TABLE solution DROP CONSTRAINT IF EXISTS solution_status_check;
ALTER TABLE solution ADD CONSTRAINT solution_status_check CHECK(status IN ('DRAFT','SUBMITTED','CHANGES_REQUESTED','APPROVED','PUBLISHED','ARCHIVED'));
CREATE INDEX IF NOT EXISTS ix_subject_active_order ON subject(is_active,display_order);
CREATE INDEX IF NOT EXISTS ix_paper_subject_order ON paper(subject_id,display_order);
CREATE INDEX IF NOT EXISTS ix_chapter_paper_order ON chapter(paper_id,display_order);
CREATE INDEX IF NOT EXISTS ix_topic_chapter_order ON topic(chapter_id,display_order);
CREATE INDEX IF NOT EXISTS ix_question_chapter_status ON question(chapter_id,status);
CREATE INDEX IF NOT EXISTS ix_qv_question_lang ON question_version(question_id,language_code,version_no DESC);
CREATE INDEX IF NOT EXISTS ix_sv_solution_lang ON solution_version(solution_id,language_code,version_no DESC);
CREATE OR REPLACE FUNCTION prevent_published_question_version_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM question q WHERE q.id=OLD.question_id AND q.status='PUBLISHED' AND q.published_version_id=OLD.id) THEN RAISE EXCEPTION 'Published question version % is immutable',OLD.id USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_immutable_published_question_version ON question_version;
CREATE TRIGGER trg_immutable_published_question_version BEFORE UPDATE OR DELETE ON question_version FOR EACH ROW EXECUTE FUNCTION prevent_published_question_version_mutation();
CREATE OR REPLACE FUNCTION prevent_published_solution_version_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM solution s WHERE s.id=OLD.solution_id AND s.status='PUBLISHED' AND s.published_version_id=OLD.id) THEN RAISE EXCEPTION 'Published solution version % is immutable',OLD.id USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_immutable_published_solution_version ON solution_version;
CREATE TRIGGER trg_immutable_published_solution_version BEFORE UPDATE OR DELETE ON solution_version FOR EACH ROW EXECUTE FUNCTION prevent_published_solution_version_mutation();
ALTER TABLE question ADD COLUMN IF NOT EXISTS published_version_id UUID REFERENCES question_version(id) ON DELETE SET NULL;
ALTER TABLE solution ADD COLUMN IF NOT EXISTS published_version_id UUID REFERENCES solution_version(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS ix_question_published_version ON question(published_version_id);
CREATE INDEX IF NOT EXISTS ix_solution_published_version ON solution(published_version_id);
